#[cfg(test)]
mod tests {
    use omnipaxos::unicache::{lru_cache::LRUniCache, FieldCache};
    #[test]
    fn lfu_cache_bincode_roundtrip_control() {
        use omnipaxos::unicache::lfu_cache::LFUniCache;
        let mut cache = LFUniCache::<String,u8>::new(3);
        cache.try_encode(&"A".to_owned());
        let serialized = bincode::serialize(&cache.clone()).unwrap();
        let mut received: LFUniCache<String,u8> = bincode::deserialize(&serialized).unwrap();
        assert_eq!(received.decode(cache.try_encode(&"A".to_owned())), "A");
    }

    #[test]
    fn lru_cache_bincode_roundtrip() {
        let mut cache = LRUniCache::<String,u8>::new(3);
        cache.try_encode(&"A".to_owned());
        // AcceptSync carries the result of cloning the leader's encoder cache.
        let follower_cache = cache.clone();
        let serialized = bincode::serialize(&follower_cache).unwrap();
        println!("serialized valid LRU follower cache into {} bytes", serialized.len());
        let _: LRUniCache<String,u8> = bincode::deserialize(&serialized).unwrap();
    }
}

#[cfg(test)]
mod leadership {
    use omnipaxos::{OmniPaxos, ClusterConfig, ServerConfig, storage::{Entry, NoSnapshot}, unicache::{UniCache, FieldCache, MaybeEncoded, lru_cache::LRUniCache}, messages::Message};
    use omnipaxos_storage::memory_storage::MemoryStorage;
    use serde::{Serialize, Deserialize};
    #[derive(Clone, Debug, Serialize, Deserialize)]
    struct Item(String);
    impl Entry for Item {
        type Snapshot = NoSnapshot;
        type Encoded = u8;
        type Encodable = String;
        type NotEncodable = ();
        type EncodeResult = MaybeEncoded<String,u8>;
        type UniCache = Cache;
    }
    #[derive(Clone, Debug, Serialize, Deserialize)]
    struct Cache(LRUniCache<String,u8>);
    impl UniCache for Cache {
        type T = Item;
        fn new() -> Self { Self(LRUniCache::new(255)) }
        fn try_encode(&mut self, e: &Item) -> MaybeEncoded<String,u8> { self.0.try_encode(&e.0) }
        fn decode(&mut self, e: MaybeEncoded<String,u8>) -> Item { Item(self.0.decode(e)) }
    }
    type Node = OmniPaxos<Item,MemoryStorage<Item>>;
    fn deliver(nodes: &mut [Node]) {
        for _ in 0..100 {
            let mut msgs: Vec<Message<Item>> = vec![];
            for n in nodes.iter_mut() { n.take_outgoing_messages(&mut msgs); }
            if msgs.is_empty() { return; }
            // Move messages without cloning or serialization, isolating cache leadership behavior.
            for m in msgs { nodes[m.get_receiver() as usize - 1].handle_incoming(m); }
        }
        panic!("did not quiesce");
    }
    fn scenario(change_leader: bool) {
        let mut nodes: Vec<Node> = (1..=3).map(|pid|
            ClusterConfig { configuration_id: 1, nodes: vec![1,2,3], flexible_quorum: None }
            .build_for_server(ServerConfig {pid, ..Default::default()}, MemoryStorage::default()).unwrap()
        ).collect();
        nodes[0].try_become_leader();
        deliver(&mut nodes);
        for i in 0..255 { nodes[0].append(Item(format!("key-{i}"))).unwrap(); deliver(&mut nodes); }
        assert!(nodes.iter().all(|n| n.get_decided_idx() == 255));
        let leader = if change_leader {
            nodes[1].try_become_leader();
            deliver(&mut nodes);
            1
        } else { 0 };
        println!("255 distinct values decided; leader now {}; appending another distinct value", leader + 1);
        nodes[leader].append(Item("next-value".into())).unwrap();
        deliver(&mut nodes);
        assert!(nodes.iter().all(|n| n.get_decided_idx() == 256));
    }
    #[test]
    fn new_leader_lru_encoding_overflow() { scenario(true); }
    #[test]
    fn unchanged_leader_full_lru_control() { scenario(false); }
}
# Continuing audit notes

Confirmed findings and controls are in report.md and audit-repro/src/lib.rs. The harness depends on captured read-only source, not the writable implementation copy. No modifications to implementation.

Unresolved targets (not findings):
- Message coalescing across repeated Promise/AcceptSync sessions: confirmed as Finding 3. Control draining buffered messages before retry passes. Consider other paths that change sessions without resetting cache, but avoid reporting the same cause twice.
- Trimming uses accepted acknowledgments although docs require all decided; inspect recovery from a lost Decide after leader trims. Need actual corruption/liveness consequence before reporting.
- Configuration-ID isolation: confirmed as Finding 4 with legitimately delayed original AcceptDecide. Report explicitly qualifies the transport condition. Cross-configuration Prepare/Compaction/ProposalForward paths remain untested and may share the same isolation cause.
- Persistent storage was source-reviewed briefly; execution of its atomicity/recovery paths remains outstanding. Serialization-error handling appears to leave next_log_key and pending batches mutated on Err (source suspicion only; not tested). The harness currently uses MemoryStorage, which is sufficient for the confirmed no-crash defects.
- Existing sync tests use a latest-value snapshot, which may hide loss of earlier independent keys or duplication. They were read but not executed in this phase.

Tool notes: rg is absent; use find/grep. Offline cargo build of independent harness succeeds. Target artifacts reside under .runtime/cargo-target and are disposable. Tests/logs/lockfile are outside .runtime. The run script records actual Cargo exit status even though expected-bug assertions fail.

## Optional-feature follow-up targets

- LRU serde empty-sequence panic is confirmed as Finding 5, with LFU passing control. Separate audit-unicache crate avoids unifying unicache into the main Value Entry harness.
- LRU and LFU Clone implementations transform encoder state into a decoder and empty the encoder. A second clone therefore appears to lose decoder contents. Check ordinary Message clone behavior separately, accounting for the documented special cache-clone semantics.
- Follower-to-leader LRU overflow is now Finding 6: full valid u8 cache, leader change, one distinct append panics in checked build. Unchanged-leader control passes. Investigate unchecked/release behavior and encoder/decoder disagreement next; do not extrapolate the checked panic to production release.
- LFU cloning reconstructs entries without carrying frequency counters or stable tie ordering. Investigate eviction consistency after AcceptSync. Not yet executed or a finding.
pub struct LRUniCache<Encodable, Encoded>
where
    Encodable: DefaultEncodable,
    Encoded: DefaultEncoded,
{
    lru_cache_encoder: LruWrapper<Encodable, Encoded>,
    lru_cache_decoder: LruWrapper<Encoded, Encodable>,
    encoding: Encoded,
    size: usize,
}

impl<Encodable, Encoded> Clone for LRUniCache<Encodable, Encoded>
where
    Encodable: DefaultEncodable,
    Encoded: DefaultEncoded,
{
    /// A cloned version of the cache but *ONLY* with the decoder. The clone is used to send the cache to followers, who will only use the decoder.
    fn clone(&self) -> Self {
        let mut cloned_decoder = LruCache::new(NonZeroUsize::new(self.size).unwrap());
        self.lru_cache_encoder
            .0
            .iter()
            .rev()
            .for_each(|(encodable, encoded)| {
                cloned_decoder.push(encoded.clone(), encodable.clone());
            });
        Self {
            lru_cache_encoder: LruWrapper(LruCache::new(NonZeroUsize::new(1).unwrap())),
            lru_cache_decoder: LruWrapper(cloned_decoder),
            encoding: self.encoding.clone(),
            size: self.size,
        }
    }
}

impl<Encodable, Encoded> Debug for LRUniCache<Encodable, Encoded>
where
    Encodable: DefaultEncodable,
    Encoded: DefaultEncoded,
{
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        f.write_str("LRUnicache")
    }
}

impl<Encodable, Encoded> FieldCache<Encodable, Encoded> for LRUniCache<Encodable, Encoded>
where
    Encodable: DefaultEncodable,
    Encoded: DefaultEncoded,
{
    fn new(size: usize) -> Self {
        let s: NonZeroUsize = NonZeroUsize::new(size).unwrap();
        Self {
            lru_cache_encoder: LruWrapper(LruCache::new(s)),
            lru_cache_decoder: LruWrapper(LruCache::new(s)),
            encoding: Encoded::default(),
            size,
        }
    }

    fn try_encode(&mut self, field: &Encodable) -> MaybeEncoded<Encodable, Encoded> {
        match self.lru_cache_encoder.get(field) {
            Some(encoding) => MaybeEncoded::<Encodable, Encoded>::Encoded(encoding.clone()),
            None => {
                if self.lru_cache_encoder.len() == self.size {
                    // cache is full, replace LRU with new item
                    let (_, popped_encoding) = self.lru_cache_encoder.pop_lru().unwrap();
                    self.lru_cache_encoder.push(field.clone(), popped_encoding);
                } else {
                    let one = Encoded::one();
                    let enc = std::mem::take(&mut self.encoding);
                    let added = enc.add(one);
                    self.lru_cache_encoder.push(field.clone(), added.clone());
                    self.encoding = added;
                }
                MaybeEncoded::NotEncoded(field.clone())
            }
        }
    }

    fn decode(&mut self, result: MaybeEncoded<Encodable, Encoded>) -> Encodable {
        match result {
            MaybeEncoded::Encoded(encoding) => {
                self.lru_cache_decoder.get(&encoding).unwrap().clone()
            }
            MaybeEncoded::NotEncoded(not_encodable) => {
                if self.lru_cache_decoder.len() == self.size {
                    // cache is full, replace LRU with new item
                    let (popped_encoded, _) = self.lru_cache_decoder.pop_lru().unwrap();
                    self.lru_cache_decoder
                        .push(popped_encoded, not_encodable.clone());
                } else {
                    let one = Encoded::one();
                    let enc = std::mem::take(&mut self.encoding);
                    let added = enc.add(one);
                    self.lru_cache_decoder
                        .push(added.clone(), not_encodable.clone());
                    self.encoding = added;
                }
                not_encodable
            }
        }
    }
}

#[cfg(feature = "serde")]
mod serialization {
    use super::*;
    use serde::{
        de::{SeqAccess, Visitor},
        ser::SerializeSeq,
    };

    impl<Encodable: DefaultEncodable, Encoded: DefaultEncodable> Serialize
        for LruWrapper<Encodable, Encoded>
    {
    Encodable: DefaultEncodable,
    Encoded: DefaultEncoded,
{
    /// A cloned version of the cache but *ONLY* with the decoder. The clone is used to send the cache to followers, who will only use the decoder.
    fn clone(&self) -> Self {
        let mut lfu_cache_decoder = LFUCache::with_capacity(self.size);
        self.lfu_cache_encoder
            .iter()
            .for_each(|(encodable, encoded)| {
                lfu_cache_decoder.set(encoded.clone(), encodable.clone());
            });
        Self {
            lfu_cache_encoder: LFUCache::with_capacity(1),
            lfu_cache_decoder,
            encoding: self.encoding.clone(),
            size: self.size,
        }
    }
}

impl<Encodable, Encoded> FieldCache<Encodable, Encoded> for LFUniCache<Encodable, Encoded>
where
    Encodable: DefaultEncodable,
    Encoded: DefaultEncoded,
{
    fn new(size: usize) -> Self {
        Self {
            lfu_cache_encoder: LFUCache::with_capacity(size),
            lfu_cache_decoder: LFUCache::with_capacity(size),
            encoding: Encoded::default(),
            size,
        }
    }

    fn try_encode(&mut self, field: &Encodable) -> MaybeEncoded<Encodable, Encoded> {
        match self.lfu_cache_encoder.get(field) {
            Some(encoding) => MaybeEncoded::<Encodable, Encoded>::Encoded(encoding.clone()),
            None => {
                if self.lfu_cache_encoder.len() == self.size {
                    // cache is full, replace LRU with new item
                    let popped_encoding = self.lfu_cache_encoder.evict_and_return_value().unwrap();
                    self.lfu_cache_encoder.set(field.clone(), popped_encoding);
                } else {
                    let one = Encoded::one();
                    let enc = std::mem::take(&mut self.encoding);
                    let added = enc.add(one);
                    self.lfu_cache_encoder.set(field.clone(), added.clone());
                    self.encoding = added;
                }
                MaybeEncoded::NotEncoded(field.clone())
            }
        }
    }

    fn decode(&mut self, result: MaybeEncoded<Encodable, Encoded>) -> Encodable {
        match result {
            MaybeEncoded::Encoded(encoding) => {
                self.lfu_cache_decoder.get(&encoding).unwrap().clone()
            }
            MaybeEncoded::NotEncoded(not_encodable) => {
                if self.lfu_cache_decoder.len() == self.size {
                    // cache is full, replace LRU with new item
                    let popped_encoded = self.lfu_cache_decoder.evict_and_return_key().unwrap();
                    self.lfu_cache_decoder
                        .set(popped_encoded, not_encodable.clone());
                } else {
                    let one = Encoded::one();
                    let enc = std::mem::take(&mut self.encoding);
                    let added = enc.add(one);
                    self.lfu_cache_decoder
                        .set(added.clone(), not_encodable.clone());
                    self.encoding = added;
                }
                not_encodable
            }
        }
    }
}

