pub mod utils;

use crate::utils::STOPSIGN_ID;
use kompact::prelude::{promise, Ask};
use omnipaxos::{
    util::{LogEntry, NodeId},
    ClusterConfig,
};
use serial_test::serial;
use utils::{TestConfig, TestSystem, Value};

const SS_METADATA: u8 = 255;

/// Verifies that the decided StopSign is correct and error is returned when trying to append after decided StopSign.
#[test]
#[serial]
fn reconfig_test() {
    let cfg = TestConfig::load("consensus_test").expect("Test config loaded");
    let mut sys = TestSystem::with(cfg);
    sys.start_all_nodes();
    sys.make_proposals(
        1,
        utils::create_proposals(1, cfg.num_proposals),
        cfg.wait_timeout,
    );

    let new_config_id = 2;
    let new_nodes: Vec<NodeId> = (cfg.num_nodes as NodeId..(cfg.num_nodes as NodeId + 3)).collect();
    let new_config = ClusterConfig {
        configuration_id: new_config_id,
        nodes: new_nodes,
        flexible_quorum: None,
    };
    let metadata = Some(vec![SS_METADATA]);

    let first_node = sys.nodes.get(&1).unwrap();
    let reconfig_f = first_node.on_definition(|x| {
        let (kprom, kfuture) = promise::<()>();
        x.paxos
            .reconfigure(new_config.clone(), metadata.clone())
            .expect("Failed to reconfigure");
        let stopsign_value = Value::with_id(STOPSIGN_ID);
        x.insert_decided_future(Ask::new(kprom, stopsign_value));
        kfuture
    });

    reconfig_f
        .wait_timeout(cfg.wait_timeout)
        .expect("Failed to collect reconfiguration future");

    first_node.on_definition(|x| {
        let decided = x
            .paxos
            .read_decided_suffix(0)
            .expect("Failed to read decided suffix");
        match decided.last().expect("Failed to read last decided entry") {
            LogEntry::StopSign(ss, decided) => {
                assert_eq!(ss.next_config, new_config);
                assert_eq!(ss.metadata, metadata);
                assert!(decided, "StopSign should be decided")
            }
            e => panic!("Last decided entry is not a StopSign: {:?}", e),
        }
    });

    let decided_nodes = sys.nodes.iter().fold(vec![], |mut x, (pid, paxos)| {
        let ss = paxos.on_definition(|x| x.paxos.is_reconfigured());
        if let Some(stop_sign) = ss {
            assert_eq!(stop_sign.next_config, new_config);
            assert_eq!(stop_sign.metadata, metadata);
            x.push(pid);
        }
        x
    });
    let quorum_size = cfg.num_nodes / 2 + 1;
    assert!(decided_nodes.len() >= quorum_size);

    let pid = *decided_nodes.last().unwrap();
    let node = sys.nodes.get(pid).unwrap();
    node.on_definition(|x| {
        x.paxos
            .append(Value::with_id(0))
            .expect_err("Should not be able to propose after decided StopSign!")
    });
    sys.shutdown();
}
use core::time::Duration;
use std::{
    collections::{HashMap, VecDeque},
    marker::PhantomData,
    time::Instant,
};

use futures::{channel::oneshot, select_biased, FutureExt, StreamExt};

use omnipaxos::{
    ballot_leader_election::Ballot,
    messages::{
        async_runtime::{AsyncRuntimeMessage, AsyncRuntimeMsg, EntryId},
        Message,
    },
    storage::{Entry, Storage},
    util::{LogEntry, NodeId},
    OmniPaxos, ProposeErr,
};

use super::{
    event::{AppendError, Command, OmniPaxosEvent},
    handle::RuntimeConfig,
    traits::{ActorEntry, AsyncRuntime},
};

/// Actor-loop-relevant subset of [`RuntimeConfig`]. Excludes the channel-capacity
/// fields, which are only needed once, to construct the channels in `spawn_actor`
/// before the actor itself is built — mirrors how `SequencePaxosConfig` in the core
/// crate trims down the public `OmniPaxosConfig` to just what that component needs.
pub(crate) struct ActorConfig {
    tick_period: Duration,
    egress_period: Duration,
    append_notify_timeout: Duration,
    max_pending_appends: usize,
    max_decided_subscribers: usize,
    max_outgoing_buffered: usize,
}

impl From<&RuntimeConfig> for ActorConfig {
    fn from(cfg: &RuntimeConfig) -> Self {
        Self {
            tick_period: cfg.tick_period,
            egress_period: cfg.egress_period,
            append_notify_timeout: cfg.append_notify_timeout,
            max_pending_appends: cfg.max_pending_appends,
            max_decided_subscribers: cfg.max_decided_subscribers,
            max_outgoing_buffered: cfg.max_outgoing_buffered,
        }
    }
}

/// A pending `append_notify` awaiting decision. Uniform representation regardless
/// of whether the entry was accepted locally (we are leader) or forwarded (we are
/// follower). The `assigned` field is filled in by either code path; the drain
/// loop treats every pending item the same way.
struct Pending<T>
where
    T: Entry,
{
    id: EntryId,
    /// The entry, retained until dispatched (accepted locally or sent as a
    /// `TaggedProposal`). While `Some`, `try_dispatch_undispatched` retries it
    /// each tick — this is what lets `append_notify` be called before a
    /// leader is known.
    undispatched: Option<T>,
