#[test]
fn delayed_old_acceptsync_erases_decided_log_after_reconnect() {
    let mut nodes: Vec<Node> = [1,2,3].into_iter().map(|pid|
        ClusterConfig { configuration_id: 1, nodes: vec"'![1,2,3], flexible_quorum: None }
        .build_for_server(ServerConfig {pid, election_tick_timeout: 1000, resend_message_tick_timeout: 1, ..Default::default()}, MemoryStorage::default()).unwrap()
    ).collect();
    nodes[0].try_become_leader();
    let mut delayed = None;
    drain(&mut nodes, |m| {
        if delayed.is_none() && matches!(m, Message::SequencePaxos(p) if p.to == 2 && matches!(p.msg, PaxosMsg::AcceptSync(_))) {
            delayed = Some(m.clone());
            false
        } else { true }
    });
    assert_eq!(nodes[1].get_current_leader(), Some((1, false)));
    // The real Promise retry causes a newer AcceptSync to complete synchronization.
    nodes[1].tick();
    drain(&mut nodes, |_| true);
    nodes[0].append(Value(10)).unwrap();
    drain(&mut nodes, |_| true);
    assert!(nodes.iter().all(|n| n.get_decided_idx() == 1 && values(n) == vec![10]));
    nodes[1].reconnected(1);
    // Deliver PrepareReq, then Prepare, leaving node 2 awaiting the new AcceptSync.
    let mut msgs = vec![];
    nodes[1].take_outgoing_messages(&mut msgs);
    for m in msgs.drain(..) { assert_eq!(m.get_receiver(), 1); nodes[0].handle_incoming(m); }
    nodes[0].take_outgoing_messages(&mut msgs);
    assert!(msgs.iter().any(|m| matches!(m, Message::SequencePaxos(p) if matches!(p.msg, PaxosMsg::Prepare(_)))));
    for m in msgs { assert_eq!(m.get_receiver(), 2); nodes[1].handle_incoming(m); }
    assert_eq!(nodes[1].get_current_leader(), Some((1, false)));
    println!("deliver delayed session-1 AcceptSync after session-2 decided value 10: {:?}", delayed);
    nodes[1].handle_incoming(delayed.unwrap());
    println!("immediately after stale sync: accepted {}, decided {}, values {:?}", nodes[1].get_accepted_idx(), nodes[1].get_decided_idx(), values(&nodes[1]));
    drain(&mut nodes, |_| true);
    println!("after all current traffic: accepted {}, decided {}, values {:?}", nodes[1].get_accepted_idx(), nodes[1].get_decided_idx(), values(&nodes[1]));
    assert_eq!(nodes[1].get_decided_idx(), 1, "a delayed old synchronization must not undo a decided entry");
    assert_eq!(values(&nodes[1]), vec![10]);
}
EOF
